'use strict';
// Demo identity only: browser-side filtering is not server authentication.
function demoActor(s){let id;try{id=sessionStorage.getItem('lazzat-demo-actor');}catch{}return id?s.staff.find(p=>p.id===id&&p.active)||{id:'denied',role:'none',name:'Kirish yopiq'}:s.staff.find(p=>p.role==='Ega'&&p.active)||{role:'none',name:'Kirish yopiq'};}
function isOwner(s){return demoActor(s).role==='Ega';}
function canBranch(s,id){const a=demoActor(s);return a.role==='Ega'||(a.branchId===id&&s.branches.some(b=>b.id===id));}
function scopedBranches(s){return s.branches.filter(b=>canBranch(s,b.id));}
function actorSelector(s){const a=demoActor(s);return `<label class="demo-identity">Demo rol <select id="demo-actor" aria-label="Demo foydalanuvchini tanlash">${s.staff.filter(p=>p.active).map(p=>`<option value="${esc(p.id)}" ${a.id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select></label>`;}
function chooseActor(id,s){if(!s.staff.some(p=>p.id===id&&p.active))throw Error('Xodim faol emas.');sessionStorage.setItem('lazzat-demo-actor',id);}
function ownerViews(s){return isOwner(s)?['overview','branches','orders','finance','dishes','daily','team','settings']:demoActor(s).role==='Menejer'?['overview','branches','orders','finance','dishes','daily']:[];}
function sellerViews(s){return isOwner(s)?navItems.map(n=>n[0]):['Menejer','Operator','Sotuvchi'].includes(demoActor(s).role)?['orders','menu']:demoActor(s).role==='Oshpaz'?['orders']:[];}
function itemCost(s,item){if(Number.isFinite(item.unitCost)&&item.unitCost>=0)return {value:item.unitCost,source:'snapshot'};const product=item.productId?s.products.find(p=>p.id===item.productId):s.products.filter(p=>p.name===item.name).length===1?s.products.find(p=>p.name===item.name):null;return Number.isFinite(product?.cost)&&product.cost>=0?{value:product.cost,source:'estimate'}:{value:0,source:'missing'};}
function snapshotCosts(s,order){order.items=order.items.map(i=>{const c=itemCost(s,i);return c.source==='missing'?i:{...i,unitCost:c.value};});}
function sellerActionAllowed(s,action,id){if(action==='close')return true;if(action==='nav')return sellerViews(s).includes(id);if(isOwner(s))return true;if(!sellerViews(s).length||!scopedBranches(s).length)return false;if(['accept','reject','ready','complete','print','delivery-info'].includes(action))return s.orders.some(o=>o.id===id&&canBranch(s,o.branch));if(['order-tab','notifications','help','demo-order'].includes(action))return true;return sellerViews(s).includes('menu')&&['menu-tab','product','categories','availability','delete-product','confirm-delete-product','rename-category','delete-category','import','import-confirm','import-template'].includes(action);}
function sellerFormAllowed(s,form){if(isOwner(s))return true;if(!scopedBranches(s).length)return false;if(['accept-form','reject-form','delivery-info-form'].includes(form.id))return s.orders.some(o=>o.id===form.dataset.id&&canBranch(s,o.branch));return sellerViews(s).includes('menu')&&['product-form','category-form','rename-category-form'].includes(form.id);}
